def[predicate](
    Topology.T4(S@Topology.ctxt.S),
    Logic.forall-typed(
        @F,
        Set(S@Topology.ctxt.S),
        Logic.forall-typed(
            @E,
            Set(S@Topology.ctxt.S),
            Logic.implies(
                Logic.and(Topology.closedSet[text](F, τ@Topology.ctxt.tau, S@Topology.ctxt.S), Topology.closedSet[text](E, τ@Topology.ctxt.tau, S@Topology.ctxt.S)),
                Logic.exists-typed(
                    @U,
                    Set(S@Topology.ctxt.S),
                    Logic.exists-typed(
                        @V,
                        Set(S@Topology.ctxt.S),
                        Logic.and(
                            Logic.and(Set.mem(U, τ@Topology.ctxt.tau), Set.mem(V, τ@Topology.ctxt.tau)), 
                            Logic.and(
                                Neq(Set.inter(U, V), Set.emptyset), 
                                Logic.and(Set.subset(F, U), Set.subset(E, V))
                            )
                        )
                    )
                )
            )
        )
    )
)
